    (("基坑", "围护", "支护", "土方", "开挖", "回填", "钢支撑", "型钢拔除", "SMW", "锚索",
      "超前支撑", "注浆钢管"), "foundation_pit"),
    # ✅ 2026-09-26 死模板修复：`earthwork`（场地平整/边坡修整/土方回填与压实）
    #    此前在 BUILDERS / TEMPLATE_META / list_templates 中齐备，却**没有任何
